    K.inserts.forEach(function(it){if(cnt[it.id]){var u=Math.round(it.add*Math.pow(c.cube/33,1.1)*(1+fp/200));lines.push([cnt[it.id]+' × '+it.label.toLowerCase(),u*cnt[it.id]])}});
