        +'<div class="s-dims two" id="o-cust" hidden><label>Genişlik (cm)<input type="number" inputmode="numeric" id="o-w" min="'+PR.door.fuoriMisura.wMin+'" max="'+PR.door.fuoriMisura.wMax+'"><small>'+PR.door.fuoriMisura.wMin+'–'+PR.door.fuoriMisura.wMax+'</small></label><label>Yükseklik (cm)<input type="number" inputmode="numeric" id="o-h" min="'+PR.door.fuoriMisura.hMin+'" max="'+PR.door.fuoriMisura.hMax+'"><small>'+PR.door.fuoriMisura.hMin+'–'+PR.door.fuoriMisura.hMax+'</small></label></div><p class="s-note" id="o-cust-n" hidden>'+esc(PR.door.fuoriMisura.note)+'</p></fieldset>';
